import {statuses,categories,sortReview,reviewLevel,prepareKorean,initialData,validate,migrate,removeCategory,renameCategory,updateItem,safeUrl} from './core.js';
const $=s=>document.querySelector(s), key='upheavel.projects.v2', legacyKey='upheavel.korean.v1';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let projectId='korean',expanded=new Set(['korean']),settingsId=null;
let data,filter='All items',query='',editing=null,draft=null,removed=null,blocked=false;
try{const raw=localStorage.getItem(key)??localStorage.getItem(legacyKey);data=prepareKorean(raw?migrate(JSON.parse(raw)):migrate(initialData()));}catch{data={version:2,projects:[],items:[]};blocked=true;$('#error').hidden=false;$('#error').textContent='Saved data could not be read. Export a copy before changing browser storage.';}
function persist(next){if(blocked){$('#note-status').textContent='Reload before editing; saved data changed or could not be read.';return false;}try{validate(next);localStorage.setItem(key,JSON.stringify(next));data=next;$('#saved').textContent='Saved in this browser';return true;}catch{$('#saved').textContent='Not saved — browser storage unavailable';$('#note-status').textContent='Not saved. Keep this window open and export a backup.';return false;}}
function options(values,selected){return Object.entries(values).map(([value,label])=>`<option value="${esc(value)}" ${value===selected?'selected':''}>${esc(label)}</option>`).join('');}
const glyphs={Grammar:'문',Vocabulary:'단',Listening:'듣',Conversation:'말',Pronunciation:'음'};
function render(){
 const active=data.projects.filter(p=>!p.archived);if(!active.some(p=>p.id===projectId)){projectId=active[0]?.id;filter='All items';}
 const project=data.projects.find(p=>p.id===projectId);
 $('#project-name').textContent=project?.name||'No projects';$('#add').disabled=!project;
 $('#categories').innerHTML=active.map(p=>`<div class="project-group"><div class="project-row"><button class="project-toggle ${p.id===projectId?'active':''}" data-project="${esc(p.id)}" ${p.id==='korean'?'':`aria-expanded="${expanded.has(p.id)}"`}><span>${p.id==='korean'?'':expanded.has(p.id)?'▾':'▸'}</span>${esc(p.name)}</button><button data-settings="${esc(p.id)}" aria-label="Manage ${esc(p.name)}">⋯</button></div>${p.id!=='korean'&&expanded.has(p.id)?`<div class="subsections">${['All items',...p.categories,...(data.items.some(i=>i.projectId===p.id&&!i.category)?['Unsectioned']:[])].map(c=>`<button data-owner="${esc(p.id)}" data-filter="${esc(c)}" class="${p.id===projectId&&filter===c?'active':''}" aria-pressed="${p.id===projectId&&filter===c}">${esc(c)}<span class="count">${data.items.filter(i=>i.projectId===p.id&&(c==='All items'||i.category===(c==='Unsectioned'?'':c))).length}</span></button>`).join('')}<button data-settings="${esc(p.id)}">＋ Subsection</button></div>`:''}</div>`).join('');
 if(!project){$('#board').innerHTML='<p class="empty">Add a project to create a board.</p>';return;}
 document.querySelector('h1').textContent=projectId==='korean'?'Review list':'Learning board';
 if(projectId==='korean'){
  const groups=[...project.categories,...(data.items.some(i=>i.projectId==='korean'&&!i.category)?['']:[])];
  $('#board').innerHTML=groups.map(category=>{const items=sortReview(data.items.filter(i=>i.projectId==='korean'&&i.category===category&&`${i.title} ${i.notes}`.toLocaleLowerCase().includes(query)));return `<section class="section review-section" aria-label="${esc(category||'Unsectioned')}"><div class="section-heading"><h2>${esc(category||'Unsectioned')}</h2><button data-add-review="${esc(category)}" aria-label="Add to ${esc(category||'Unsectioned')}">＋ Add</button></div><ul class="review-list">${items.map(i=>`<li class="review-row ${i.status==='learned'?'studied':''}"><input type="checkbox" data-studied="${esc(i.id)}" aria-label="Studied ${esc(i.title)}" ${i.status==='learned'?'checked':''}><button class="study-topic" data-study="${esc(i.id)}" aria-label="Study ${esc(i.title)}">${esc(i.title)}</button><span class="study-level">${reviewLevel(i)}</span><button data-open="${esc(i.id)}" aria-label="Notes for ${esc(i.title)}">Notes${i.notes||i.links.length?' •':''}</button></li>`).join('')||'<li class="empty">No items.</li>'}</ul></section>`}).join('');return;
 }
 $('#board').innerHTML=Object.entries(statuses).map(([status,label])=>{const items=data.items.filter(i=>i.projectId===projectId&&i.status===status&&(filter==='All items'||i.category===(filter==='Unsectioned'?'':filter))&&`${i.title} ${i.notes}`.toLocaleLowerCase().includes(query));return `<section class="section" data-status="${status}" aria-label="${label}"><div class="section-heading"><h2>${label}</h2><span class="count">${items.length}</span><button data-add="${status}" aria-label="Add to ${label}">＋ Add</button></div><div class="cards">${items.map(i=>`<article class="card"><button class="card-title" data-open="${esc(i.id)}" aria-label="Open ${esc(i.title)}"><span class="glyph" aria-hidden="true">${glyphs[i.category]||'•'}</span><strong>${esc(i.title)}</strong></button><span class="kind">${esc(i.category||'Unsectioned')}${i.links.length?` · ${i.links.length} link${i.links.length===1?'':'s'}`:''}</span><button data-open="${esc(i.id)}">Notes</button><select data-move="${esc(i.id)}" aria-label="Section for ${esc(i.title)}">${options(statuses,i.status)}</select></article>`).join('')||`<p class="empty">${query?'No matching items.':'No items in this section.'}</p>`}</div></section>`}).join('');
}
function openItem(id,status='curious',category=null){
 editing=id;draft=id?structuredClone(data.items.find(i=>i.id===id)):{id:crypto.randomUUID(),title:'',projectId,category:category??(['All items','Unsectioned'].includes(filter)?'':filter),status,notes:'',links:[]};
 $('#status').closest('label').hidden=draft.projectId==='korean';$('#category').closest('label').firstChild.textContent=draft.projectId==='korean'?'Section':'Subsection';
 $('#dialog-title').textContent=id?draft.title:'Add item';$('#title').value=draft.title;$('#status').innerHTML=options(statuses,draft.status);$('#category').innerHTML=options(Object.fromEntries([['','Unsectioned'],...data.projects.find(p=>p.id===draft.projectId).categories.map(c=>[c,c])]),draft.category);$('#notes').value=draft.notes;$('#remove').hidden=!id;$('#done').textContent=id?'Done':'Add item';$('#note-status').textContent=id?'Changes save automatically':'Enter a title to add this item.';renderLinks();$('#notebook').showModal();$('#title').focus();
}
function renderLinks(){ $('#links').innerHTML=draft.links.map((l,n)=>`<div class="link-row"><input data-link-name="${n}" aria-label="Link ${n+1} name" placeholder="Name" maxlength="160" value="${esc(l.name)}"><input data-link-url="${n}" aria-label="Link ${n+1} URL" placeholder="https://…" maxlength="2000" value="${esc(l.url)}"><a data-link-open="${n}" href="${esc(safeUrl(l.url)||'#')}" target="_blank" rel="noopener noreferrer" ${safeUrl(l.url)?'':'hidden'}>Open ↗</a><button type="button" data-remove-link="${n}" aria-label="Remove link ${n+1}">×</button></div>`).join('');}
function readDraft(){draft.title=$('#title').value;draft.status=$('#status').value;draft.category=$('#category').value;draft.notes=$('#notes').value;document.querySelectorAll('[data-link-name]').forEach(e=>draft.links[Number(e.dataset.linkName)].name=e.value);document.querySelectorAll('[data-link-url]').forEach(e=>draft.links[Number(e.dataset.linkUrl)].url=e.value);}
function save(){readDraft();if(!draft.title.trim()){ $('#note-status').textContent='A title is required.';return false;}const next=editing?updateItem(data,editing,draft):validate({...data,items:[...data.items,draft]});if(!persist(next))return false;editing=draft.id;$('#note-status').textContent='Saved';render();return true;}
function close(){if(draft&&($('#title').value.trim()||editing)&&!save())return;$('#notebook').close();draft=null;editing=null;}
$('#add').onclick=()=>{if(projectId)openItem(null)};$('#search').oninput=e=>{query=e.target.value.toLocaleLowerCase();render();};
$('#categories').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.settings){settingsId=b.dataset.settings;showSettings();}else if(b.dataset.project){projectId=b.dataset.project;filter='All items';if(expanded.has(projectId))expanded.delete(projectId);else expanded.add(projectId);render();}else if(b.dataset.filter){projectId=b.dataset.owner;filter=b.dataset.filter;render();}};
$('#board').onclick=e=>{const study=e.target.closest('[data-study]');if(study){openStudy(study.dataset.study,study);return;}const open=e.target.closest('[data-open]'),add=e.target.closest('[data-add]');if(open)openItem(open.dataset.open);else if(add)openItem(null,add.dataset.add);else{const review=e.target.closest('[data-add-review]');if(review)openItem(null,'curious',review.dataset.addReview);}};
$('#board').onchange=e=>{if(e.target.matches('[data-studied]')){const id=e.target.dataset.studied;persist(updateItem(data,id,{status:e.target.checked?'learned':'curious'}));render();document.querySelector(`[data-studied="${CSS.escape(id)}"]`)?.focus();return;}if(e.target.matches('[data-move]')){persist(updateItem(data,e.target.dataset.move,{status:e.target.value}));render();}};
$('#editor').oninput=()=>{readDraft();if(editing)save();document.querySelectorAll('[data-link-open]').forEach(a=>{const url=safeUrl(draft.links[Number(a.dataset.linkOpen)].url);a.hidden=!url;a.href=url||'#';});};
$('#editor').onchange=()=>{if(editing)save();};
$('#editor').onsubmit=e=>{e.preventDefault();if(save()){$('#notebook').close();draft=null;editing=null;}};
$('#close').onclick=close;$('#notebook').oncancel=e=>{e.preventDefault();close();};
$('#add-link').onclick=()=>{readDraft();if(draft.links.length>=100)return;draft.links.push({name:'',url:''});renderLinks();if(editing)save();};
$('#links').onclick=e=>{const b=e.target.closest('[data-remove-link]');if(b){readDraft();draft.links.splice(Number(b.dataset.removeLink),1);renderLinks();if(editing)save();}};
$('#remove').onclick=()=>{const item=data.items.find(i=>i.id===editing);if(persist({...data,items:data.items.filter(i=>i.id!==editing)})){removed=item;$('#undo').hidden=false;$('#notebook').close();draft=null;editing=null;render();}};
$('#restore').onclick=()=>{if(removed&&persist({...data,items:[...data.items,removed]})){removed=null;$('#undo').hidden=true;render();}};
$('#export').onclick=()=>{let copy=structuredClone(data);if(draft){readDraft();if(draft.title.trim()){copy.items=copy.items.filter(i=>i.id!==draft.id);copy.items.push(draft);}}const blob=new Blob([blocked?localStorage.getItem(key)||localStorage.getItem(legacyKey)||JSON.stringify(copy):JSON.stringify(copy,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='upheavel-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('#import').onclick=()=>$('#file').click();$('#file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>15000000)throw new Error('Backup is too large.');const incoming=prepareKorean(migrate(JSON.parse(await file.text())));if(!confirm('Replace all Upheavel projects with the backup? Export your current board first if you want to keep it.'))return;if(persist(incoming)){removed=null;$('#undo').hidden=true;render();}}catch(err){$('#error').hidden=false;$('#error').textContent=err.message;}finally{e.target.value='';}};
$('#export-draft').onclick=()=>$('#export').click();
window.addEventListener('storage',e=>{if(e.key===key){blocked=true;$('#error').hidden=false;$('#error').textContent='This board changed in another tab. Reload to use its latest version. Export any open draft first.';}});
window.addEventListener('beforeunload',e=>{if(draft&&($('#title').value.trim()||editing)&&!save()){e.preventDefault();e.returnValue='';}});
function showSettings(){
 const project=data.projects.find(p=>p.id===settingsId&&!p.archived);
 $('#project-dialog-title').textContent=project?`Manage ${project.name}`:'Projects';$('#project-error').textContent='';
 $('#project-settings').innerHTML=`<form id="create-project"><label>New project<input name="name" maxlength="100" required placeholder="League of Legends, Career…"></label><button class="primary">Add project</button></form>${project?`<hr><form id="rename-project"><label>Project name<input name="name" maxlength="100" required value="${esc(project.name)}"></label><button>Rename project</button></form><h3>${project.id==='korean'?'Sections':'Subsections'}</h3>${project.categories.map((c,n)=>`<form class="category-edit" data-category-index="${n}"><input name="name" aria-label="Subsection name ${n+1}" maxlength="100" required value="${esc(c)}"><button>Rename</button><button type="button" data-delete-category="${n}" aria-label="Delete ${esc(c)} subsection">Delete</button></form>`).join('')}<form id="create-category"><label>New ${project.id==='korean'?'section':'subsection'}<input name="name" maxlength="100" required></label><button>Add ${project.id==='korean'?'section':'subsection'}</button></form><p class="settings-help">Deleting a subsection keeps its items under All items and Unsectioned.</p><button id="delete-project">Delete project</button><p class="settings-help">Deleted projects and their items can be restored below.</p>`:''}<hr><h3>Deleted projects</h3>${data.projects.filter(p=>p.archived).map(p=>`<div class="restore-project"><span>${esc(p.name)}</span><button data-restore-project="${esc(p.id)}">Restore</button></div>`).join('')||'<p class="settings-help">None.</p>'}`;
 if(!$('#project-dialog').open)$('#project-dialog').showModal();
}
function commitSettings(next){if(persist(next)){render();showSettings();return true;}$('#project-error').textContent='Changes were not saved. Reload if this board changed in another tab.';return false;}
$('#new-project').onclick=()=>{settingsId=null;showSettings();};$('#manage-projects').onclick=()=>{settingsId=projectId;showSettings();};$('#close-projects').onclick=()=>$('#project-dialog').close();
$('#project-settings').onsubmit=e=>{e.preventDefault();const form=e.target;const name=new FormData(form).get('name')?.trim();if(!name)return;try{
 let next=structuredClone(data);const project=next.projects.find(p=>p.id===settingsId);
 if(form.id==='create-project'){if(next.projects.some(p=>!p.archived&&p.name.toLocaleLowerCase()===name.toLocaleLowerCase()))throw new Error('A project with this name already exists.');const id=crypto.randomUUID();next.projects.push({id,name,categories:[],archived:false});if(persist(next)){projectId=id;settingsId=id;filter='All items';expanded.add(id);render();showSettings();}return;}
 if(form.id==='rename-project'){if(next.projects.some(p=>p.id!==settingsId&&!p.archived&&p.name.toLocaleLowerCase()===name.toLocaleLowerCase()))throw new Error('A project with this name already exists.');project.name=name;}
 else {if(['all items','unsectioned'].includes(name.toLowerCase()))throw new Error('That name is reserved.');if(form.id==='create-category'){if(project.categories.some(c=>c.toLowerCase()===name.toLowerCase()))throw new Error('This subsection already exists.');project.categories.push(name);}
 else{const old=project.categories[Number(form.dataset.categoryIndex)];if(project.categories.some(c=>c!==old&&c.toLowerCase()===name.toLowerCase()))throw new Error('This subsection already exists.');next=renameCategory(data,settingsId,old,name);if(filter===old)filter=name;}}
 commitSettings(next);
 }catch(error){$('#project-error').textContent=error.message;}};
$('#project-settings').onclick=e=>{const b=e.target.closest('button');if(!b)return;try{
 if(b.dataset.deleteCategory!==undefined){const project=data.projects.find(p=>p.id===settingsId);const name=project.categories[Number(b.dataset.deleteCategory)];if(commitSettings(removeCategory(data,settingsId,name))){filter='All items';render();}}
 else if(b.id==='delete-project'){const next=structuredClone(data);next.projects.find(p=>p.id===settingsId).archived=true;commitSettings(next);}
 else if(b.dataset.restoreProject){const next=structuredClone(data);next.projects.find(p=>p.id===b.dataset.restoreProject).archived=false;commitSettings(next);}
 }catch(error){$('#project-error').textContent=error.message;}};
render();

async function openStudy(id,button){
 const item=data.items.find(i=>i.id===id);if(!item)return;
 const {openChat}=await import('/chat.js');openChat(item);
}
